    private static func validTaskAttachmentList(_ value: Any?) -> Bool {
        guard let rows = value as? [[String: Any]], rows.count <= 1_000,
              let data = try? JSONSerialization.data(withJSONObject: rows), data.count <= 2_000_000 else { return false }
        let ids = rows.compactMap { $0["id"] as? String }
        return ids.count == rows.count && Set(ids).count == ids.count
            && ids.allSatisfy { !$0.isEmpty && $0.utf16.count <= 500 }
    }

    private static func validTaskAttachmentHalf(_ value: Any?) -> Bool {
        guard let half = value as? [String: Any], Set(half.keys) == Set(["base", "value"]) else { return false }
        return validTaskAttachmentList(half["base"]) && validTaskAttachmentList(half["value"])
    }

    private static func validTaskAttachmentOwner(_ value: Any?) -> Bool {
        guard let owner = value as? [String: Any], Set(owner.keys) == Set(["kind", "taskId", "attachments"]),
              owner["kind"] as? String == "task", let taskID = owner["taskId"] as? String,
              !taskID.isEmpty, taskID.utf16.count <= 500 else { return false }
        return validTaskAttachmentList(owner["attachments"])
    }

    private static func validTaskLinkEditing(_ value: Any?) -> Bool {
        guard let edit = value as? [String: Any], Set(edit.keys) == Set(["attachmentId", "title", "uri"]),
              let id = edit["attachmentId"] as? String, !id.isEmpty, id.utf16.count <= 500,
              let title = edit["title"] as? String, title.utf16.count <= 100_000,
              let uri = edit["uri"] as? String, uri.utf16.count <= 100_000 else { return false }
        return true
    }

    init(queue: DispatchQueue, databaseURL: URL, bundleURL: URL, legacyStorage: LegacyRNStorage? = nil,
         rnAdoptionContainerURL: URL? = nil,
         deviceStorage: (containerURL: URL, bundleIdentifier: String)? = nil,
         workspaceMode: NativeWorkspaceMode = .personal, restrictedFixtureRoot: URL? = nil, localRequests: NativeAttachmentLocalRequests,
         reminderAdmissions: NativeReminderEffects, dropboxAuthorization: NativeDropboxAuthorizationBinding? = nil) {
        self.dropboxAuthorization = dropboxAuthorization
        self.queue = queue
        self.workspaceMode = workspaceMode
        self.restrictedFixtureRoot = restrictedFixtureRoot
        self.localRequests = localRequests
        self.reminderAdmissions = reminderAdmissions
        self.databaseURL = databaseURL
        self.bundleURL = bundleURL
        diagnosticsFile = NativeDiagnosticsLogFile(libraryRoot: databaseURL.deletingLastPathComponent())
        backupExportFile = NativeBackupExportFile(libraryRoot: databaseURL.deletingLastPathComponent())
        backupImportFile = NativeBackupImportFile(libraryRoot: databaseURL.deletingLastPathComponent())
        backupOperationFiles = NativeBackupOperationFiles(libraryRoot: databaseURL.deletingLastPathComponent())
        self.legacyStorage = legacyStorage
        self.rnAdoptionContainerURL = rnAdoptionContainerURL
        self.deviceStorageLocation = deviceStorage
        journalURL = databaseURL.appendingPathExtension("pending.json")
        editorDrafts = EditorDraftStore(databaseURL: databaseURL)
    }

    private func loadPendingJournal(checkingEditorSnapshot: Bool = true) throws -> PendingCommand? {


        guard let journalData = try readJournalBytes(maximumBytes: nil,
            failure: HostFailure("Invalid pending command journal"), singleLink: false) else { return nil }
        guard let raw = try NativeJSON.jsonObject(with: journalData) as? [String: Any],
              Set(raw.keys).isSubset(of: (raw["method"] as? String).flatMap(VoiceAction.init(commit:)) == nil
                ? ["version", "method", "argumentsJSON", "terminal", "editorDraft"]
                : ["version", "method", "argumentsJSON", "terminal", "voiceFiles"]),
              raw["editorDraft"] == nil || (raw["editorDraft"] as? [String: Any]).map({
                  Set($0.keys) == Set(["id", "sessionID", "taskID", "generation", "method", "argumentsJSON"])
              }) == true,
              let saved = try? JSONDecoder().decode(PendingCommand.self, from: journalData) else {
            throw HostFailure("Invalid pending command journal")
        }
        guard saved.version == 2 else { throw HostFailure("Unsupported pending command journal; raw captures cannot be safely replanned") }
        if saved.method == "inboxUndoCommit" {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Process Inbox Undo journal")
            }
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String, value.utf8.count <= 4096 else {
                    throw HostFailure("INVALID_INPUT: Malformed Process Inbox Undo terminal")
                }
                if name == "success" {
                    guard try NativeJSON.hasUniqueObjectKeys(value) else {
                        throw HostFailure("INVALID_INPUT: Malformed Process Inbox Undo terminal")
                    }
                }
            }
        }
        if boardOrderEnvelope(saved) != nil {
            guard journalData.count <= Self.boardOrderJournalLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)) else {
                throw HostFailure("INVALID_INPUT: Malformed prepared Board order journal")
            }
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      payload["_0"] is String else { throw HostFailure("INVALID_INPUT: Malformed Board order terminal") }
            }
        }
        if saved.method == "calendarEventTaskCommit" || raw["method"] as? String == "calendarEventTaskCommit" {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)) else {
                throw HostFailure("INVALID_INPUT: Malformed prepared Calendar event task journal")
            }
        }
        if CalendarSubscriptionOperation(commitMethod: saved.method) != nil
            || String(decoding: journalData, as: UTF8.self).contains("calendarSubscriptionSettingCommit")
            || String(decoding: journalData, as: UTF8.self).contains("calendarSubscriptionAddCommit") {
            guard journalData.count <= Self.calendarSubscriptionSettingJournalLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)) else {
                throw HostFailure("INVALID_INPUT: Malformed prepared calendar subscription journal")
            }
        }
        if let operation = CalendarSubscriptionOperation(commitMethod: saved.method) {
            guard Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Calendar subscription journal has unknown members")
            }
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String, value.utf8.count <= 1024 else {
                    throw HostFailure("INVALID_INPUT: Calendar subscription terminal is malformed")
                }
                if name == "success" { _ = try Self.calendarSubscriptionResult(value, operation: operation) }
                else { guard isDefiniteRejection(value, method: saved.method) else { throw Self.deviceStorageInvalid } }
            }
        }
        if saved.method == "deviceCalendarSettingCommit" {
            guard journalData.count <= Self.deviceCalendarSettingJournalLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)) else {
                throw HostFailure("INVALID_INPUT: Malformed prepared Device Calendar setting journal")
            }
        }
        if saved.method == Self.appleReminderMethod {
            guard journalData.count <= Self.appleReminderLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else { throw Self.appleReminderFailure }
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], Set(encoded.keys) == Set(["success"]),
                      let payload = encoded["success"] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      payload["_0"] is String else { throw Self.appleReminderFailure }
            }
            _ = try appleReminderItem(saved)
        }
        if saved.method == Self.pomodoroMethod {
            guard journalData.count <= Self.pomodoroJournalLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else { throw Self.pomodoroFailure }
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]), payload["_0"] is String else { throw Self.pomodoroFailure }
            }
            _ = try pomodoroJournalArguments(saved)
        }
        if saved.method == "captureLinesCommit" {
            guard journalData.count <= Self.captureLinesJournalLimit,
                  try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed capture lines journal")
            }
            let operation = try captureLinesOperation(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed capture lines terminal")
                }
                if name == "success" {
                    guard value.utf8.count <= 64 * 1024, try NativeJSON.hasUniqueObjectKeys(value),
                          Self.equalJSON(try NativeJSON.jsonObject(with: Data(value.utf8)), operation.result) else {
                        throw HostFailure("INVALID_INPUT: Capture lines terminal differs from its frozen result")
                    }
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed capture lines refusal")
                    }
                }
            }
        }
        if ["inboxTasksAddTagCommit", "projectTasksAddTagCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Add tag journal")
            }
            _ = try taskListAddTagJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Add tag terminal")
                }
                if name == "success" {
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Add tag refusal")
                    }
                }
            }
        }
        if ["inboxTasksRemoveTagCommit", "projectTasksRemoveTagCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Remove tag journal")
            }
            _ = try taskListRemoveTagJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Remove tag terminal")
                }
                if name == "success" {
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Remove tag refusal")
                    }
                }
            }
        }

        if ["projectTasksDeleteCommit", "projectTasksDeleteUndoCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Project bulk Delete journal")
            }
            _ = try taskListDeleteJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Project bulk Delete terminal")
                }
                if name == "success" { try validatePreparedAcknowledgment(saved, value: value) }
                else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Project bulk Delete refusal")
                    }
                }
            }
        }
        if ["inboxTasksOrganizeCommit", "projectTasksOrganizeCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Organize journal")
            }
            _ = try taskListOrganizeJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Organize terminal")
                }
                if name == "success" {
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Organize refusal")
                    }
                }
            }
        }
        if ["inboxOrganizeDestinationCreateCommit", "projectOrganizeDestinationCreateCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Inbox Organize destination creation journal")
            }
            _ = try taskListOrganizeDestinationCreateJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Inbox Organize destination creation terminal")
                }
                if name == "success" {
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Inbox Organize destination creation refusal")
                    }
                }
            }
        }
        if ["inboxTasksMoveCommit", "projectTasksMoveCommit"].contains(saved.method) {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Move journal")
            }
            _ = try taskListMoveJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Move terminal")
                }
                if name == "success" {
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Inbox bulk Move refusal")
                    }
                }
            }
        }
        if saved.method == "trashItemsRestoreCommit" {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Trash bulk Restore journal")
            }
            _ = try trashItemsRestoreJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Trash bulk Restore terminal")
                }
                if name == "success" {
                    guard value.utf8.count <= 1024, try NativeJSON.hasUniqueObjectKeys(value) else {
                        throw HostFailure("INVALID_INPUT: Malformed Trash bulk Restore success")
                    }
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Trash bulk Restore refusal")
                    }
                }
            }
        }
        if saved.method == "trashItemsPurgeCommit" {
            guard try NativeJSON.hasUniqueObjectKeys(String(decoding: journalData, as: UTF8.self)),
                  Set(raw.keys) == Set(["version", "method", "argumentsJSON"])
                    || Set(raw.keys) == Set(["version", "method", "argumentsJSON", "terminal"]) else {
                throw HostFailure("INVALID_INPUT: Malformed Trash purge journal")
            }
            _ = try trashItemsPurgeJournalArguments(saved)
            if let terminal = raw["terminal"] {
                guard let encoded = terminal as? [String: Any], encoded.count == 1,
                      let name = encoded.keys.first, ["success", "rejected"].contains(name),
                      let payload = encoded[name] as? [String: Any], Set(payload.keys) == Set(["_0"]),
                      let value = payload["_0"] as? String else {
                    throw HostFailure("INVALID_INPUT: Malformed Trash purge terminal")
                }
                if name == "success" {
                    guard value.utf8.count <= 1024, try NativeJSON.hasUniqueObjectKeys(value) else {
                        throw HostFailure("INVALID_INPUT: Malformed Trash purge success")
                    }
                    try validatePreparedAcknowledgment(saved, value: value)
                } else {
                    guard value.utf8.count <= 4096, isDefiniteRejection(value, method: saved.method) else {
                        throw HostFailure("INVALID_INPUT: Malformed Trash purge refusal")
                    }
                }
            }
        }
        if saved.method == Self.ownedDiscardMethod {
            _ = try decodeOwnedDiscardJournal(journalData, checkingNative: true)
        } else if saved.method == Self.cleanupMethod {
            _ = try decodeCleanupJournal(journalData)
            guard try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes)?.bytes == journalData else { throw Self.cleanupFailure }
        } else if saved.method == Self.projectDownloadMethod {
            _ = try projectDownloadJournal(saved)
            guard try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes)?.bytes == journalData else { throw Self.projectDownloadFailure }
        } else if saved.method == Self.projectFileAddMethod {
            _ = try projectFileAddJournal(saved)
            guard try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes)?.bytes == journalData else { throw Self.projectFileAddFailure }
        } else if saved.method == Self.mixedSaveMethod {
            guard try ownedJournalBytes() == journalData else { throw Self.ownedSaveFailure }
            _ = try decodeMixedSaveJournal(journalData, checkingNative: true)
        } else if saved.method == Self.ownedSaveMethod {
            _ = try decodeOwnedSaveJournal(journalData, checkingNative: true)
        } else if saved.method == "projectLifecycleCommit" {
            _ = try projectLifecycleJournalArguments(saved)
        } else {
            _ = try journalArguments(saved, checkingEditorSnapshot: checkingEditorSnapshot)
        }
        switch saved.terminal {
        case .success(let value):
            _ = try NativeJSON.jsonObject(with: Data(value.utf8), options: [.fragmentsAllowed])
            if saved.method == "dataSetting" { try validateDataSettingAcknowledgment(value) }
            if saved.method == "gettingStarted" { try validateGettingStartedAcknowledgment(value) }
            if saved.method == "reminderCompletionCommit" { try validateReminderCompletionResult(value) }
            if saved.method == "reminderSnoozeCommit" {
                let args = try reminderSnoozeJournalArguments(saved)
                guard let raw = args.first as? String else { throw Self.reminderSnoozeInvalid }
                try validateReminderSnoozeAlarm(value, request: raw)
            }
        case .rejected(let message):
            guard isDefiniteRejection(message, method: saved.method) else { throw HostFailure("Invalid terminal command journal") }
        case nil: break
        }
        if attachmentDraftEvidence, ![Self.ownedDiscardMethod, Self.ownedSaveMethod, Self.mixedSaveMethod].contains(saved.method) {
            try validateRetainedOrdinaryCommand(saved)
        }
        return saved
    }

    private static var rnAdoptionFailure: HostFailure { HostFailure("RN adoption storage requires recovery") }

    private func prepareRNAdoptionDirectories() throws {
        guard let container = rnAdoptionContainerURL, rnAdoptionDirectories.isEmpty else { throw Self.rnAdoptionFailure }
        let root = Darwin.open(container.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW_ANY | O_CLOEXEC)
        guard root >= 0 else { throw Self.rnAdoptionFailure }
        rnAdoptionDirectories.append((container, root))
        var parent = root, path = container
        for component in ["Documents", "SQLite"] {
            if mkdirat(parent, component, 0o700) == 0 {
                guard fsync(parent) == 0 else { throw Self.rnAdoptionFailure }
            } else if errno != EEXIST { throw Self.rnAdoptionFailure }
            let child = openat(parent, component, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard child >= 0 else { throw Self.rnAdoptionFailure }
            path.appendPathComponent(component, isDirectory: true)
            rnAdoptionDirectories.append((path, child))
            parent = child
        }
        try verifyRNAdoptionDirectories()
        try verifyRNAdoptionDatabaseFiles()
        lockFD = openat(parent, databaseURL.appendingPathExtension("host-lock").lastPathComponent,
                        O_CREAT | O_RDWR | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC, 0o600)
        guard lockFD >= 0, fsync(parent) == 0 else { throw Self.rnAdoptionFailure }
        try verifyRNAdoptionDirectories()
    }

    private func verifyRNAdoptionDirectories() throws {
        guard rnAdoptionDirectories.count == 3 else { throw Self.rnAdoptionFailure }
        for directory in rnAdoptionDirectories {
            let namedFD = Darwin.open(directory.url.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW_ANY | O_CLOEXEC)
            guard namedFD >= 0 else { throw Self.rnAdoptionFailure }
            defer { Darwin.close(namedFD) }
            var descriptor = stat(), named = stat()
            guard fstat(directory.fd, &descriptor) == 0, fstat(namedFD, &named) == 0,
                  descriptor.st_dev == named.st_dev, descriptor.st_ino == named.st_ino else { throw Self.rnAdoptionFailure }
        }
        if lockFD >= 0, let parent = rnAdoptionDirectories.last {
            var descriptor = stat(), named = stat()
            guard fstat(lockFD, &descriptor) == 0,
                  descriptor.st_mode & S_IFMT == S_IFREG, descriptor.st_nlink == 1,
                  fstatat(parent.fd, databaseURL.appendingPathExtension("host-lock").lastPathComponent, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1,
                  descriptor.st_dev == named.st_dev, descriptor.st_ino == named.st_ino else { throw Self.rnAdoptionFailure }
        }
    }

    private func verifyRNAdoptionDatabaseFiles() throws {
        do {
            for suffix in ["", "-wal", "-shm", "-journal"] {
                _ = try Self.bindingIdentity(URL(fileURLWithPath: databaseURL.path + suffix))
            }
        } catch { throw Self.rnAdoptionFailure }
    }

    func start(retainingReminderResponseIDs: [String]?) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        let retentionJSON: String
        if let ids = retainingReminderResponseIDs {
            guard ids.count <= 128, Set(ids).count == ids.count,
                  ids.allSatisfy({ UUID(uuidString: $0)?.uuidString.lowercased() == $0 }) else {
                throw CoreHostRejection(message: "INVALID_INPUT: Invalid reminder receipt retention")
            }
            retentionJSON = String(decoding: try JSONSerialization.data(withJSONObject: ids), as: UTF8.self)
        } else { retentionJSON = "null" }
        guard !closed else { throw HostFailure("Core host is closed") }
        guard reminderEffectsTurn == nil, pomodoroAlarmTurn == nil else { throw NativeReminderEffects.unavailable }
        do {
            if started {
                if rnAdoptionContainerURL != nil { try verifyRNAdoptionDirectories() }
                try denyCleanupOwner()
                return try startupWindow(retentionJSON: retentionJSON)
            }
            try validateRestrictedFixtureStorage()
            let source = try String(contentsOf: bundleURL, encoding: .utf8)
            guard !source.isEmpty else { throw HostFailure("Core bundle is empty") }
            if rnAdoptionContainerURL != nil {
                try prepareRNAdoptionDirectories()
            } else {
                try FileManager.default.createDirectory(at: databaseURL.deletingLastPathComponent(), withIntermediateDirectories: true,
                                                        attributes: [.posixPermissions: 0o700])
                try DurableFile.sync(databaseURL.deletingLastPathComponent().deletingLastPathComponent(), directory: true)
                lockFD = open(databaseURL.appendingPathExtension("host-lock").path, O_CREAT | O_RDWR | O_NOFOLLOW, 0o600)
            }
            guard lockFD >= 0, flock(lockFD, LOCK_EX | LOCK_NB) == 0 else { throw HostFailure("Native database is already in use or cannot be locked") }
            if let container = rnAdoptionContainerURL {
                guard let location = deviceStorageLocation else { throw Self.rnAdoptionFailure }
                try verifyRNAdoptionDirectories()
                let snapshot = try LegacyRNStorage(containerURL: container, bundleIdentifier: location.bundleIdentifier)
                guard !snapshot.deviceNamespaceSnapshot().hasPopulatedLegacyCopy else { throw Self.rnAdoptionFailure }
                legacyStorage = snapshot
            }
            if workspaceMode == .personal {
            if rnAdoptionContainerURL == nil, let location = deviceStorageLocation {
                deviceStorage = try? NativeDeviceKV(containerURL: location.containerURL, bundleIdentifier: location.bundleIdentifier)
                #if DEBUG
                if let deviceStorage { faults?.configureDeviceStorage?(deviceStorage) }
                #endif
            }
            let calendarFiles: NativeAttachmentFiles?
            if let container = rnAdoptionContainerURL {
                attachmentJobs = try? NativeAttachmentFileJobs(rnAdoptionContainerURL: container)
                calendarFiles = attachmentJobs?.files
                if attachmentJobs != nil {
                    NSLog("Native iOS RN candidate attachment roots bound releaseCheck=v1.3.9/ios-rn-candidate-attachment-roots outcome=bound")
                }
            } else {
                attachmentJobs = try? NativeAttachmentFileJobs(libraryRoot: databaseURL.deletingLastPathComponent())
                calendarFiles = try? NativeAttachmentFiles(libraryRoot: databaseURL.deletingLastPathComponent())
            }
            let readCalendarFile: (String, NativeAttachmentCancellation) throws -> Data = { uri, cancellation in
                guard let calendarFiles else { throw NativeCalendarReadError.unavailable }
                return try calendarFiles.readCalendarFile(uri, checkCancellation: cancellation.check)
            }
            attachmentGeneration &+= 1
            #if DEBUG
            httpJobs = NativeHTTPJobs(registry: localRequests, faults: faults)
            if let httpJobs { faults?.configureHTTPJobs?(httpJobs) }
            secretJobs = try NativeSecretJobs(registry: localRequests, faults: faults)
            if let secretJobs { faults?.configureSecretJobs?(secretJobs) }
            calendarJobs = NativeCalendarJobs(registry: localRequests,
                readFile: readCalendarFile,
                readerFactory: faults?.calendarReaderFactory ?? { NativeCalendarReader() })
            if let calendarJobs { faults?.configureCalendarJobs?(calendarJobs) }
            cryptoJobs = NativeCryptoJobs(registry: localRequests, faults: faults)
            if let cryptoJobs { faults?.configureCryptoJobs?(cryptoJobs) }
            #else
            httpJobs = NativeHTTPJobs(registry: localRequests)
            secretJobs = NativeSecretJobs(registry: localRequests)
            calendarJobs = NativeCalendarJobs(registry: localRequests, readFile: readCalendarFile)
            cryptoJobs = NativeCryptoJobs(registry: localRequests)
            #endif
            }
            let httpGeneration = attachmentGeneration
            httpJobs?.setWake { [weak self] in
                guard let self else { return }
                self.queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == httpGeneration else { return }
                    self.scheduleAttachmentIdle(immediate: true)
                }
            }
            secretJobs?.setWake { [weak self] in
                guard let self else { return }
                self.queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == httpGeneration else { return }
                    self.scheduleAttachmentIdle(immediate: true)
                }
            }
            cryptoJobs?.setWake { [weak self] in
                guard let self else { return }
                self.queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == httpGeneration else { return }
                    self.scheduleAttachmentIdle(immediate: true)
                }
            }
            calendarJobs?.setWake { [weak self] in
                guard let self else { return }
                self.queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == httpGeneration, !self.localRequests.isClosing else { return }
                    self.scheduleAttachmentIdle(immediate: true)
                }
            }
            if let jobs = attachmentJobs {
                #if DEBUG
                attachmentHooks?.configureJobs?(jobs)
                #endif
                let generation = attachmentGeneration
                jobs.setWake { [weak self] in
                    guard let self else { return }
                    self.queue.async { [weak self] in
                        guard let self, self.attachmentGeneration == generation else { return }
                        self.scheduleAttachmentIdle(immediate: true)
                    }
                }
            }
            if pending == nil { pending = try loadPendingJournal() }

            let cleanupRecovery = pending?.method == Self.cleanupMethod
            let recoveringCaptureLines = pending?.method == "captureLinesCommit"
            let recoveringTrashItemsPurge = pending?.method == "trashItemsPurgeCommit"
            let recoveringPomodoro = pending?.method == Self.pomodoroMethod
            let recoveringAppleReminder = pending?.method == Self.appleReminderMethod
            if cleanupRecovery {
                var original = stat()
                guard lstat(databaseURL.path, &original) == 0, original.st_mode & S_IFMT == S_IFREG else { throw Self.cleanupFailure }
            }

            if !cleanupRecovery && !recoveringCaptureLines && !recoveringTrashItemsPurge && !recoveringPomodoro && !recoveringAppleReminder { try? backupExportFile.discardInterruptedExports() }


            if let command = pending, command.method == "backupDocumentCommit" {
                _ = try backupDocumentArguments(command)
            }
            let retainedBackup = try pending.flatMap { command -> String? in
                if command.method == "backupDocumentCommit" { return try backupOperationReference(command).id }
                if command.method == "captureLinesCommit" { return try captureLinesOperation(command).reference.id }
                if command.method == Self.appleReminderMethod { return try appleReminderItem(command).reference.id }
                return nil
            }


            if !cleanupRecovery && !recoveringCaptureLines && !recoveringTrashItemsPurge && !recoveringPomodoro && !recoveringAppleReminder { try? backupOperationFiles.discardUnreferencedOperations(retaining: Set(retainedBackup.map { [$0] } ?? [])) }

            if !cleanupRecovery && !recoveringCaptureLines && !recoveringTrashItemsPurge && !recoveringPomodoro && !recoveringAppleReminder { try? backupImportFile.discardUnreferencedCopies(retaining: Set(backupSelections.values.map { $0.selection.reference.id })) }
            guard let runtime = JSContext() else { throw HostFailure("Cannot create JavaScriptCore runtime") }
            context = runtime
            #if DEBUG
            faults?.configureRuntimeLifetime?(self, runtime, runtime.virtualMachine)
            #endif
            installBridge(runtime)
            runtime.evaluateScript(source, withSourceURL: bundleURL)
            try checkException()
            guard let host = runtime.objectForKeyedSubscript("MindwtrHost"), !host.isUndefined, !host.isNull else {
                throw HostFailure("Core bundle has no host contract")
            }
            try validatePendingStartupContent(retainedBackup: retainedBackup, recoveringTrashItemsPurge: recoveringTrashItemsPurge)
            try validatePendingStartupWorkflow()
            try validatePendingStartupSettings()
            if pending != nil {
                NSLog("Native iOS startup validation phase completed releaseCheck=v1.3.9/ios-startup-validation-frame outcome=checked")
            }
            var legacy = cleanupRecovery ? nil : try legacyStorage?.bootState()
            if let legacy {
                _ = try invoke("legacyCheck", arguments: [legacy.stateJSON, legacy.backupJSON])
                if !FileManager.default.fileExists(atPath: databaseURL.path), legacyStorage?.hasStoredValues == true {
                    let state = try NativeJSON.jsonObject(with: Data(legacy.stateJSON.utf8)) as? [String: Any]
                    let hadSQLite = state?["jsonAhead"] as? Bool == true || state?["reconciled"] as? Bool == true
                        || state?["backupVersion"] as? String != nil


                    guard !hadSQLite, !legacy.backupJSON.isEmpty else {
                        throw HostFailure("Legacy library database is missing; recovery is required")
                    }
                }
            }
            if rnAdoptionContainerURL != nil {
                try verifyRNAdoptionDirectories()
                try verifyRNAdoptionDatabaseFiles()
            }
            let sqlite = try SQLiteBridge(url: databaseURL)
            database = sqlite
            calendarPushDatabaseBinding = try? Self.bindingIdentity(databaseURL)
            #if DEBUG
            let guardedFaults = HostIOFaults()
            guardedFaults.beforeSQL = { [unowned self] sql in
                try self.requireCalendarSubscriptionSettingTurn(publication: self.calendarSubscriptionSQLPublication(sql))
                try self.requireCleanupTurn()
                try self.requireRetainedOrdinaryTurn(requirePreparation: true)
                try self.requireProjectFileAddTurn()
                try self.requireProjectDownloadTurn()
                try self.faults?.beforeSQL?(sql)
                try self.requireCalendarSubscriptionSettingTurn(publication: self.calendarSubscriptionSQLPublication(sql))
                try self.requireRetainedOrdinaryTurn(requirePreparation: true)
                try self.requireProjectFileAddTurn()
                try self.requireProjectDownloadTurn()
                try self.requireCleanupTurn()
            }
            guardedFaults.afterSQL = { [unowned self] sql in
                if let turn = self.cleanupTurn {
                    if sql == "BEGIN IMMEDIATE" { turn.transaction = true }
                    if sql == "ROLLBACK" { turn.transaction = false }
                }
                try self.faults?.afterSQL?(sql)
                try self.requireCalendarSubscriptionSettingTurn(publication: self.calendarSubscriptionSQLPublication(sql))
                try self.requireRetainedOrdinaryTurn(requirePreparation: true)
                try self.requireProjectFileAddTurn()
                try self.requireProjectDownloadTurn()
                try self.requireCleanupTurn()
            }
            guardedFaults.checkpoint = { [unowned self] in try self.requireCleanupTurn(); try self.faults?.checkpoint?(); try self.requireCleanupTurn() }
            guardedFaults.afterIntegrity = { [unowned self] in try self.requireCleanupTurn(); try self.faults?.afterIntegrity?(); try self.requireCleanupTurn() }
            sqlite.faults = guardedFaults
            #endif
            if cleanupRecovery, let command = pending { _ = try captureCleanupTurn(command: command) }
            try sqlite.prepareRecovery(at: databaseURL.appendingPathExtension("prewrite"))
            if cleanupRecovery, let turn = cleanupTurn {
                let id = UUID(), cancellation = NativeAttachmentCancellation()
                localRequests.register(cancellation, id: id)
                do {
                    defer { localRequests.remove(id) }
                    _ = try executeCleanup(turn, cancellation: cancellation)
                }
                legacy = try legacyStorage?.bootState()
                if let legacy { _ = try invoke("legacyCheck", arguments: [legacy.stateJSON, legacy.backupJSON]) }
            }
            try requireProjectFileAddTurn()
        try requireProjectDownloadTurn()
            recoveryActivationPending = pending != nil
            projectFileAddTurn?.activationPending = recoveryActivationPending
            projectDownloadTurn?.activationPending = recoveryActivationPending
            #if DEBUG && os(iOS) && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
            try applyCaptureAIFixtureBeforeBoot()
            #endif
            _ = try invoke(recoveryActivationPending ? "bootRecovery" : "boot", arguments: [legacy?.stateJSON ?? "", legacy?.backupJSON ?? ""])
            try requireProjectFileAddTurn()
        try requireProjectDownloadTurn()
            if rnAdoptionContainerURL != nil {
                guard let location = deviceStorageLocation else { throw Self.rnAdoptionFailure }
                try verifyRNAdoptionDirectories()
                deviceStorage = try NativeDeviceKV(containerURL: location.containerURL, bundleIdentifier: location.bundleIdentifier)
                #if DEBUG
                if let deviceStorage { faults?.configureDeviceStorage?(deviceStorage) }
                #endif
                try verifyRNAdoptionDirectories()
                NSLog("Native iOS RN candidate storage admitted releaseCheck=v1.3.9/ios-rn-candidate-storage outcome=ready")
            }
            started = true
            emitCleanupAcknowledgement()
            projectFileAddTurn?.expectedStarted = true
            projectDownloadTurn?.expectedStarted = true


            return try startupWindow(retentionJSON: retentionJSON)
        } catch {
            if !(error is CoreHostAppLockRecovery) && !(error is CoreHostProjectFileAddRecovery) && !(error is CoreHostProjectFileAvailabilityRecovery) { releaseRuntime() }
            throw error
        }
    }

    func cancelAppLockRecovery() throws {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, unresolvedAppLockRecovery, let command = pending,
              command.method == "appLockCommit" else { throw HostFailure("No unresolved App lock recovery") }

        _ = try finish(command, with: .rejected("STALE_REVISION: App lock outcome unknown; pending change cancelled"))
        unresolvedAppLockRecovery = false
        NSLog("Native iOS App lock recovery cancelled releaseCheck=v1.3.4/ios-app-lock outcome=cancelled")
    }

