                          let fireAt = entry["fireAtMs"] as? NSNumber, !Self.isBoolean(fireAt),
                          fireAt.doubleValue.isFinite, fireAt.doubleValue.rounded() == fireAt.doubleValue,
                          abs(fireAt.doubleValue) <= 8_640_000_000_000_000,
