        if taskDownloadDropbox(config) { return [NativeDropboxSelectedAdmission.legacyTokens, "@mindwtr_sync_encryption_key_v1"] }
        return taskDownloadSelfHosted(config) ? taskDownloadCloudLegacyKeys : taskDownloadLegacyKeys
