                  (metadata["message"] as? String).map({ !$0.isEmpty && $0.utf16.count <= 512 }) == true,
                  (metadata["undoLabel"] as? String).map({ !$0.isEmpty && $0.utf16.count <= 80 }) == true else { throw Self.ownedSaveFailure }
