    func retryPending() throws -> String? {
        dispatchPrecondition(condition: .onQueue(queue))
        guard aiTextConfigurationTurn == nil, aiConfigurationTurn == nil, !(pending.map { Self.aiTextConfigurationCommitMethods.contains($0.method) } ?? false) else { throw CoreHostRejection(message: "NOT_READY: AI text configuration save requires its exact typed retry") }
        let readmittedTurn = aiReadmittedSettingTurn?.setting
        for setting in NativeAIReadmittedSetting.allCases {
            let turnBlocks = readmittedTurn == setting || (setting == .reasoningEffort && readmittedTurn == .geminiThinkingBudget)
            guard !turnBlocks, pending?.method != setting.commitMethod else {
                throw CoreHostRejection(message: "NOT_READY: " + setting.subject + " save requires its exact typed retry")
            }
        }
        guard calendarAccessTurn == nil else { throw CoreHostRejection(message: "NOT_READY: Calendar access is still awaiting its owner") }
        guard notificationSettingTurn == nil, deviceCalendarSettingTurn == nil, calendarSubscriptionSettingTurn == nil else { throw CoreHostRejection(message: "NOT_READY: Settings edit is still awaiting its owner") }
        #if DEBUG && os(iOS) && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
        if boardMoveFixtureArmed, let command = pending, command.method == "boardCommit",
           command.argumentsJSON == boardMoveFixtureOriginal { boardMoveFixtureRetry = true }
        #endif
        let command = pending
        let method = command?.method
        let terminal = try resolvePending()
        try resumeActivationIfNeeded()
        guard let terminal else {
            let reply = backupUnreturnedReply
            backupUnreturnedReply = nil
            return reply
        }
        if case .success = terminal, let command {
            rememberConfirmedSomedayMove(command)
            rememberConfirmedTaskCancellation(command)
            rememberConfirmedTaskCompletion(command)
            rememberConfirmedTaskDelete(command)
            rememberConfirmedProjectDelete(command)
        }
        let reply = try publicValue(terminal, method: method)
        if method == "backupDocumentCommit" { backupUnreturnedReply = nil }
        return reply
    }

    private func validateDraftAcknowledgment(_ command: PendingCommand, value: String? = nil) throws {
        let encoded = try invoke("draftValidate", arguments: journalArguments(command))
        guard let validation = try NativeJSON.jsonObject(with: Data(encoded.utf8)) as? [String: Any] else {
            throw HostFailure("Malformed editor validation")
        }
        let expected: [String: Any]?
        let id: String
        if Self.isInteger(validation["version"], equalTo: 1) {
            guard Set(validation.keys) == Set(["version", "id"]), let identifier = validation["id"] as? String else {
                throw HostFailure("Malformed legacy editor validation")
            }
            expected = nil; id = identifier
        } else {
            guard Self.isInteger(validation["version"], equalTo: 2), Set(validation.keys) == Set(["version", "result"]),
                  let result = validation["result"] as? [String: Any], Set(result.keys) == Set(["id", "draft"]),
                  let identifier = result["id"] as? String, result["draft"] is [String: Any] else {
                throw HostFailure("Malformed editor validation")
            }
            expected = result; id = identifier
        }
        if let value {
            guard let result = try NativeJSON.jsonObject(with: Data(value.utf8)) as? [String: Any],
                  Set(result.keys) == Set(["id", "draft"]), result["id"] as? String == id,
                  result["draft"] is [String: Any], expected == nil || Self.equalJSON(expected, result) else {
                throw HostFailure("Malformed editor acknowledgment")
            }
        }
    }

    private func publicValue(_ terminal: TerminalResult, method: String?) throws -> String {
        let value = try terminal.value()
        if method == Self.pomodoroMethod {
            return try Self.ownedJSON(["kind": "confirmed", "result": Self.pomodoroResult(value), "projectionReloaded": lastPomodoroProjectionReloaded])
        }
        guard method == "inboxPreparedCommit" else { return value }
        let result = try NativeJSON.jsonObject(with: Data(value.utf8))
        return String(decoding: try JSONSerialization.data(withJSONObject: ["kind": "saved", "result": result], options: [.sortedKeys]), as: UTF8.self)
    }

    private func resumeActivationIfNeeded() throws {
        guard recoveryActivationPending else { return }
        _ = try invoke("resumeActivation", arguments: [])
        if let turn = retainedOrdinaryTurn, case .alreadyOwedActive = turn.mode, pending == nil {
            try requireRetainedOrdinaryTurn()
            recoveryActivationPending = false
            retainedOrdinaryTurn = nil
        } else { recoveryActivationPending = false }
        NSLog("Native iOS journal recovery releaseCheck=v1.3.3/native-ios-journal-recovery outcome=recovered")
    }

    private func resolvePending() throws -> TerminalResult? {
        try denyCleanupOwner()
        guard started, !closed else { throw HostFailure("Core host is not ready; retry startup") }
        guard let command = pending else { return nil }
        if VoiceAction(commit: command.method) != nil {
            guard recoveryActivationPending || voiceCommitAllowed else { throw HostFailure("NOT_READY: Voice save requires its exact typed retry") }
            return .success(try executeVoice(command, binding: newVoiceBinding(recovery: true), cancellation: NativeAttachmentCancellation()))
        }
        if command.method == Self.appleReminderMethod {
            try bindAppleReminderJournal(command)
            if !appleReminderRemovalPending { try persist(command) }
            return try executeAppleReminderItem(command)
        }
        if command.method == Self.projectDownloadMethod { throw CoreHostProjectFileAvailabilityRecovery() }
        if command.method == Self.projectFileAddMethod { throw CoreHostProjectFileAddRecovery() }
        if command.method == Self.mixedSaveMethod { return try executeMixedSave(command, cancellation: NativeAttachmentCancellation()) }
        if command.method == Self.ownedDiscardMethod {
            return try executeOwnedDiscard(command, cancellation: NativeAttachmentCancellation())
        }
        if command.method == Self.ownedSaveMethod {
            if let terminal = command.terminal { return try finishOwnedSave(command, with: terminal) }

            try persist(command)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.beforeSaveCommit)
            #endif
            let captured = try requireOwnedSaveInvocation(command)
            let value = try invoke(command.method, arguments: [captured.envelopeJSON])
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveCommit)
            #endif
            return try finishOwnedSave(command, with: .success(value))
        }
        if let operation = CalendarSubscriptionOperation(commitMethod: command.method) {
            return try withCalendarSubscriptionSettingOwner(operation: operation) {
                guard let raw = try journalArguments(command).first as? String else { throw Self.deviceStorageInvalid }
                calendarSubscriptionSettingTurn?.envelopeJSON = raw
                _ = try invoke(operation.rawValue + "Validate", arguments: [raw])
                if let terminal = command.terminal { return try finish(command, with: terminal) }
                try persist(command)
                let terminal: TerminalResult
                do { terminal = .success(try invokeCalendarSubscriptionSettingCommit(command)) }
                catch let error as HostFailure where error.message.hasPrefix("STALE_REVISION:") && recoveryActivationPending {
                    terminal = .rejected(error.message)
                }
                return try finish(command, with: terminal)
            }
        }
        if command.method == "deviceCalendarSettingCommit" {
            return try withDeviceCalendarSettingOwner {
                guard let raw = try journalArguments(command).first as? String else { throw Self.deviceStorageInvalid }
                deviceCalendarSettingTurn?.envelopeJSON = raw
                _ = try invoke("deviceCalendarSettingValidate", arguments: [raw])
                if let terminal = command.terminal { return try finish(command, with: terminal) }
                try persist(command)
                return try finish(command, with: .success(invokeDeviceCalendarSettingCommit(command)))
            }
        }
        _ = try beginRetainedOrdinaryTurn(command: command)
        ordinaryMutationDepth += 1
        defer {
            ordinaryMutationDepth -= 1


            if pending == nil {
                if let turn = retainedOrdinaryTurn, case .alreadyOwedActive = turn.mode,
                   recoveryActivationPending {                                        }
                else { retainedOrdinaryTurn = nil }
            }
        }
        if command.method == Self.pomodoroMethod {
            _ = try invoke("pomodoroTransitionValidate", arguments: pomodoroJournalArguments(command))
            if case .rejected(let message) = command.terminal { return try finish(command, with: .rejected(message)) }
            try allowRetainedOrdinaryPreparation()
            try persist(command)
            return try executePomodoro(command, replayOnly: command.terminal != nil, allowUnsettled: false)
        }
        if command.method == "reminderSnoozeCommit" {
            let args = try reminderSnoozeJournalArguments(command)
            guard let raw = args.first as? String else { throw Self.reminderSnoozeInvalid }
            _ = try frozenReminderSnooze(command)
            if let terminal = command.terminal { return try finish(command, with: terminal) }
            let value: String
            if recoveryActivationPending {
                do { value = try savedReminderSnooze(raw) }
                catch let failure as HostFailure where failure.message.hasPrefix("STALE_REVISION:") {
                    return try finish(command, with: .rejected(failure.message))
                }
            } else {
                try persist(command)
                do { value = try invoke("reminderSnoozeRetry", arguments: [raw]) }
                catch let failure as HostFailure where failure.message.hasPrefix("STALE_REVISION:") {
                    return try finish(command, with: .rejected(failure.message))
                }
            }
            try publishReminderSnooze(command, value: value)
            return try finish(command, with: .success(value))
        }
        if command.method == "reminderCompletionCommit" {
