            if turn.transaction {
                do { _ = try turn.database.execute("ROLLBACK"); turn.transaction = false }
                catch { throw Self.cleanupFailure }
            }


            if turn.command == nil && turn.terminal == nil { cleanupTurn = nil }
            throw Self.cleanupFailure
        }
