            return
        }
        if command.method == "deviceCalendarSettingCommit" { _ = try journalArguments(command) }
        if command.method == "taskCancellationUndoCommit", try cancellationUndoIsComplete(command) {


            _ = try journalArguments(command)
        }
        if command.method == Self.mixedSaveMethod {
            let data = try ownedEncoded(command)
            guard data.count <= Self.ownedSaveMaximumBytes else { throw Self.ownedSaveFailure }
            _ = try mixedSaveJournal(command, checkingNative: false)
            try requireOwnedJournalWriteIdentity(command)
            try mixedGuard?()
            let previous = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes)
            #if DEBUG
            try faults?.journalWrite?()
            #endif
            guard try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes) == previous else { throw Self.ownedSaveFailure }
            try requireOwnedJournalWriteIdentity(command)
            try mixedGuard?()
            try DurableFile.write(data, to: journalURL, privateDraft: true)
            return
        }
        if command.method == Self.ownedSaveMethod || command.method == Self.ownedDiscardMethod {
            if command.method == Self.ownedDiscardMethod,
               try ownedDiscardJournal(command, checkingNative: false).version >= 5 {
                guard let mixedGuard else { throw Self.ownedDiscardFailure }
                let data = try ownedEncoded(command)
                guard data.count <= Self.ownedSaveMaximumBytes else { throw Self.ownedDiscardFailure }
                try requireOwnedJournalWriteIdentity(command)
                try mixedGuard()
                #if DEBUG
                try faults?.journalWrite?()
                #endif
                try mixedGuard()
                try requireOwnedJournalWriteIdentity(command)
                try DurableFile.write(data, to: journalURL, privateDraft: true)
                return
            }
            let data = try ownedEncoded(command)
            guard data.count <= Self.ownedSaveMaximumBytes else { throw Self.ownedSaveFailure }
            if command.method == Self.ownedDiscardMethod { _ = try ownedDiscardJournal(command, checkingNative: false) }
            else { _ = try ownedSaveJournal(command, checkingNative: false) }
            try requireOwnedJournalWriteIdentity(command)
            let discardIdentity = command.method == Self.ownedDiscardMethod ? try ownedDiscardIdentity(journalURL) : nil
            #if DEBUG
            try faults?.journalWrite?()
            #endif
            try requireOwnedJournalWriteIdentity(command)
            if command.method == Self.ownedDiscardMethod {
                guard try ownedDiscardIdentity(journalURL) == discardIdentity else { throw Self.ownedDiscardFailure }
            }
            try DurableFile.write(data, to: journalURL, privateDraft: true)
            return
        }
        if let turn = retainedOrdinaryTurn {
            try requireRetainedOrdinaryTurn(requirePreparation: true)
            _ = try ordinaryJournalArguments(command)
            guard let expected = turn.command, Self.retainedCommandMatches(expected, command) else { throw Self.retainedOrdinaryFailure }
        }
        try requireBoardOrderEncodedSize(command)
        #if DEBUG
        try faults?.journalWrite?()
        #endif
        try requireRetainedOrdinaryTurn(requirePreparation: true)
        let bytes = try ownedEncoded(command)
        if boardOrderEnvelope(command) != nil {
            guard bytes.count <= Self.boardOrderJournalLimit else { throw HostFailure("INVALID_INPUT: Board order journal exceeds native byte budget") }
        }
        do { try DurableFile.write(bytes, to: journalURL) }
        catch {


            if let turn = retainedOrdinaryTurn {
                try requireRetainedOrdinaryTurn(checkingJournal: false)
