              notificationSettingTurn == nil, !notificationSettingOwnerAccess,
              aiTextConfigurationTurn == nil, !aiTextConfigurationOwnerAccess, aiConfigurationTurn == nil,
              aiReadmittedSettingTurn == nil, aiReadmittedSettingOwnerAccess.isEmpty,
              deviceCalendarSettingTurn == nil, calendarSubscriptionSettingTurn == nil,
              calendarPushTurn == nil, retainedCalendarPushTurn == nil, calendarFileCaptureTurn == nil,
              calendarAccessTurn == nil, reminderSnoozeMutation == nil, !reminderOwnerAccess,
              appleRemindersAccess == nil, !appleReminderJournalOwned, !appleReminderJournalNeedsSync,
              !appleReminderRemovalPending, appleReminderJournalBinding == nil,
              backupSelections.isEmpty, !backupReplayReadOnly, backupUnreturnedReply == nil, !invoking else {
            throw CoreHostRetirementError.refused
        }
        do {
            guard try loadPendingJournal() == nil, try editorDrafts.read() == nil,
                  !attachmentDraftEvidence else { throw CoreHostRetirementError.refused }
            if deviceStorageLocation != nil {
                guard let deviceStorage else { throw CoreHostRetirementError.unavailable }
                try deviceStorage.validateWorkspaceRetirement()
            }
            guard let context, let host = context.objectForKeyedSubscript("MindwtrHost"),
                  let status = host.invokeMethod("iosWorkspaceRetirementStatus", withArguments: []), status.isString,
                  let text = status.toString(), text.utf8.count <= 1024 else { throw CoreHostRetirementError.unavailable }
            try checkException()
            guard let value = try NativeJSON.jsonObject(with: Data(text.utf8)) as? [String: Any],
                  Set(value.keys) == Set(["version", "ready", "pending", "uncertain"]),
                  Self.isInteger(value["version"]), (value["version"] as? NSNumber)?.intValue == 1,
                  let ready = value["ready"] as? NSNumber, CFGetTypeID(ready) == CFBooleanGetTypeID(), ready.boolValue,
                  let pending = value["pending"] as? NSNumber, CFGetTypeID(pending) == CFBooleanGetTypeID(),
                  let uncertain = value["uncertain"] as? NSNumber, CFGetTypeID(uncertain) == CFBooleanGetTypeID() else {
                throw CoreHostRetirementError.unavailable
            }
            guard !uncertain.boolValue else { throw CoreHostRetirementError.unavailable }
            guard !pending.boolValue else { throw CoreHostRetirementError.refused }
        } catch let error as CoreHostRetirementError { throw error }
        catch { throw CoreHostRetirementError.unavailable }
    }

    func validateWorkspaceShutdown() throws {
        dispatchPrecondition(condition: .onQueue(queue))
        guard closed, !started, context == nil, database == nil, lockFD < 0,
              !fileSyncCloseFailed, fileSyncTurn == nil, deviceStorage == nil,
              httpJobs == nil, secretJobs == nil, calendarJobs == nil, cryptoJobs == nil,
              attachmentJobs == nil, appleRemindersJobs == nil else { throw CoreHostRetirementError.unavailable }
    }

    func shutdown() {
        dispatchPrecondition(condition: .onQueue(queue))
        closed = true
        startupRecovery = nil
        if let jobs = appleRemindersJobs { Task { await jobs.closeAndDrain() }; appleRemindersJobs = nil }
        releaseRuntime()
    }

    private func releaseRuntime() {
        dropboxTurn?.jobs.closeAndDrain(); dropboxTurn = nil
        gmailJobs?.close(); gmailJobs = nil
        gmailReceipts?.close(); gmailReceipts = nil
        cloudKitJobs?.closeAndDrain(); cloudKitJobs = nil
        voiceWarmEnvelope = nil
        _ = retireVoiceOperations()
        if let turn = fileSyncTurn {
            do { try turn.jobs.closeAndDrain() } catch { fileSyncCloseFailed = true }
            turn.cancellation.setCancellationHandler(nil)
            fileSyncTurn = nil
        }
        if let turn = calendarPushTurn ?? retainedCalendarPushTurn {
            try? retryCalendarPushState(turn)
            try? turn.effects.retryPublication()
            try? turn.writes?.cancelAndDrain()
        }
        calendarPushTurn = nil; retainedCalendarPushTurn = nil
        calendarPushReady.removeAll(); calendarPushObserver = nil
        calendarPushDatabaseBinding = nil
        appleReminderJournalOwned = false; appleReminderJournalNeedsSync = false; appleReminderRemovalPending = false
        appleReminderJournalBinding = nil; completedAppleReminderSnapshot = nil
        if let capture = calendarFileCaptureTurn { abortCalendarFileCapture(capture.id) }
        removeReminderObserver(nil)
        searchObserver = nil
        reminderAdmissions.clearOrdinaryReadyWake()
        reminderEffectsTurn = nil
        pomodoroAlarmTurn = nil
        aiTextConfigurationTurn = nil; aiTextConfigurationOwnerAccess = false; aiTextConfigurationRetired = false
        aiConfigurationTurn?.cancellation.cancel(); aiConfigurationTurn?.discovery?.http.shutdown()
        aiConfigurationTurn = nil; aiConfigurationSession = nil
        aiReadmittedSettingTurn = nil; aiReadmittedSettingOwnerAccess = []; aiReadmittedSettingRetired = []
        captureAITurn?.live = false; captureAITurn = nil
        notificationSettingTurn = nil; notificationSettingOwnerAccess = false
        deviceCalendarSettingTurn = nil
        calendarSubscriptionSettingTurn = nil
        calendarAccessTurn = nil
        startupRecovery = startupRecovery?.releasingRuntime()
        reminderOwnerAccess = false
        reminderSourceStale = false
        foregroundCleanupCancellation = nil
        foregroundCleanupActive = false
        cleanupTurn = nil
        projectDownloadTurn = nil
        projectDownloadAcknowledgedTurn = nil
        projectFileAddTurn = nil
        retainedOrdinaryTurn = nil
        attachmentGeneration &+= 1
        attachmentIdlePump?.cancel(); attachmentIdlePump = nil
        retireTaskAIAnswer(nil)
        taskAITurn?.handle.cancel(); taskAITurn?.http.shutdown(); taskAITurn = nil
        httpJobs?.shutdown(); httpJobs = nil
        secretJobs?.shutdown(); secretJobs = nil
        calendarJobs?.shutdown(); calendarJobs = nil
        cryptoJobs?.shutdown(); cryptoJobs = nil
        reminderSnoozeMutation = nil
        deviceStorage?.close(); deviceStorage = nil
        ioBodySource = nil
        attachmentJobs?.shutdown(); attachmentJobs = nil
        providerCopy = nil
        taskDownloadTurn = nil
        projectAvailabilityTurn = nil
        encryptionUnlockTurn = nil
        started = false
        recoveryActivationPending = false
        confirmedChecklistMoveEnvelope = nil
        confirmedChecklistMoveUndoEnvelope = nil
        confirmedProjectToSectionEnvelope = nil
        confirmedTaskPromoteEnvelope = nil
        confirmedRowTaskFocusEnvelope = nil
        confirmedRowTaskDatesEnvelope = nil
        confirmedRowTaskDestinationEnvelope = nil
        referenceProjectNextActionOrigin = nil
        confirmedInboxDecisionEnvelope = nil
        confirmedInboxUndoEnvelope = nil
        context = nil
        database?.close()
        database = nil
        if lockFD >= 0 { flock(lockFD, LOCK_UN); Darwin.close(lockFD); lockFD = -1 }
        for directory in rnAdoptionDirectories { Darwin.close(directory.fd) }
        rnAdoptionDirectories.removeAll()
        if rnAdoptionContainerURL != nil { legacyStorage = nil }
    }
}


enum NativeBoardOrderJournalBudget {
    static let maximumBytes = 2_000_000
    static func require(_ initial: Data, acknowledged: Data) throws {
        guard initial.count <= maximumBytes, acknowledged.count <= maximumBytes else {
            throw HostFailure("INVALID_INPUT: Board order journal exceeds native byte budget")
        }
    }
}
